// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // Admissible domain: real token address, valid reserves, fee within the enforced cap.
        vm.assume(baseToken != address(0));
        vm.assume(uint256(uint160(baseToken)) > 10);
        vm.assume(nft != address(0));
        vm.assume(uint256(uint160(nft)) > 10);
        feeRate = uint16(bound(feeRate, 0, 5000));

        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            assertTrue(c.baseToken() == baseToken);
        } catch {
            assertTrue(false, "initialize reverted on admissible input");
        }
    }
}

